def intersection(interval1, interval2):
    """Determine if the length of intersection of two closed integer intervals is prime."""
    def is_prime(n: int) -> bool:
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    a1, b1 = interval1
    a2, b2 = interval2

    left = max(a1, a2)
    right = min(b1, b2)

    if left >= right:
        return "NO"

    length = right - left  # closed intervals length in unit gaps

    return "YES" if is_prime(length) else "NO"
